describe("localDayKey", () => {
  it("uses the target timezone, not UTC", () => {
    // 2026-08-18T05:30Z is still 2026-08-17 22:30 in Los Angeles.
    expect(localDayKey(new Date("2026-08-18T05:30:00Z"), LA)).toBe("2026-08-17");
  });

  it("agrees with UTC when the instant is mid-day local", () => {
