- [ ] **Step 3: Implement `src/util/dates.ts`**

All week arithmetic happens on UTC-anchored calendar dates derived from a local day key, which is why DST cannot shift it.

```typescript
/** "YYYY-MM-DD" for the given instant in the given IANA timezone. */
export function localDayKey(d: Date, tz: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: tz,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(d);
  const get = (type: string): string => {
    const p = parts.find((x) => x.type === type);
    if (!p) throw new Error(`missing date part: ${type}`);
    return p.value;
  };
  return `${get("year")}-${get("month")}-${get("day")}`;
}

function keyToUTC(dayKey: string): Date {
  const [y, m, d] = dayKey.split("-").map(Number) as [number, number, number];
  return new Date(Date.UTC(y, m - 1, d));
}

function utcToKey(d: Date): string {
  return d.toISOString().slice(0, 10);
}

/** The calendar day before `dayKey`. DST-proof: pure calendar arithmetic. */
export function prevDayKey(dayKey: string): string {
  const d = keyToUTC(dayKey);
  d.setUTCDate(d.getUTCDate() - 1);
  return utcToKey(d);
}

/** UTC midnight of the Monday starting the ISO week that contains `dayKey`. */
export function mondayUTC(dayKey: string): Date {
  const d = keyToUTC(dayKey);
  const dow = d.getUTCDay() || 7; // Mon=1 .. Sun=7
  d.setUTCDate(d.getUTCDate() - (dow - 1));
  return d;
}

/** "YYYY-Www" ISO-8601 week key (Monday start, week 1 contains the first Thursday). */
export function isoWeekKey(dayKey: string): string {
  const d = keyToUTC(dayKey);
  const dow = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dow); // the Thursday of this ISO week
  const isoYear = d.getUTCFullYear();
  const yearStart = Date.UTC(isoYear, 0, 1);
  const week = Math.ceil(((d.getTime() - yearStart) / 86_400_000 + 1) / 7);
  return `${isoYear}-W${String(week).padStart(2, "0")}`;
}
```

