```typescript
import type { Activity, LastActivity, TrainingStats } from "../types";
import { isoWeekKey, localDayKey, mondayUTC, prevDayKey } from "../util/dates";

const DAY = 86_400_000;

export interface DetailExtra {
  sufferScore: number | null;
  achievementCount: number;
}

function median(sorted: number[]): number {
  const n = sorted.length;
  const mid = n >> 1;
  if (n % 2 === 1) return sorted[mid]!;
  return (sorted[mid - 1]! + sorted[mid]!) / 2;
}

export function summarize(
  activities: Activity[],
  detail: DetailExtra | null,
  now: Date,
  tz: string,
): TrainingStats {
  const nowMs = now.getTime();

  const inWindow = activities
    .filter((a) => {
      const t = Date.parse(a.startDate);
      return Number.isFinite(t) && t <= nowMs && nowMs - t <= 30 * DAY;
    })
    .sort((a, b) => Date.parse(b.startDate) - Date.parse(a.startDate));

  const last = inWindow[0] ?? null;
  const prev = inWindow[1] ?? null;

  const daysSinceLast = last ? Math.floor((nowMs - Date.parse(last.startDate)) / DAY) : null;
  const gapBeforeLast =
    last && prev ? Math.floor((Date.parse(last.startDate) - Date.parse(prev.startDate)) / DAY) : null;

  const within = (a: Activity, days: number): boolean => nowMs - Date.parse(a.startDate) <= days * DAY;
  const a7 = inWindow.filter((a) => within(a, 7));
  const a28 = inWindow.filter((a) => within(a, 28));

  const load7d = a7.reduce((sum, a) => sum + a.movingTimeSeconds, 0);
  const load28d = a28.reduce((sum, a) => sum + a.movingTimeSeconds, 0);
  const loadWeeklyAvg28d = load28d / 4;
  const acuteChronicRatio = loadWeeklyAvg28d > 0 ? load7d / loadWeeklyAvg28d : null;

  // Day and week membership, bucketed in the display timezone.
  const dayKeys = new Set(inWindow.map((a) => localDayKey(new Date(a.startDate), tz)));
  const weekKeys = new Set([...dayKeys].map(isoWeekKey));

  // Walk back from the most recent active week, one week at a time.
  let streakWeeks = 0;
  if (last) {
    let cursor = mondayUTC(localDayKey(new Date(last.startDate), tz));
    while (weekKeys.has(isoWeekKey(cursor.toISOString().slice(0, 10)))) {
      streakWeeks++;
      cursor = new Date(cursor.getTime() - 7 * DAY); // safe: cursor is UTC midnight
    }
  }

  // Calendar-day arithmetic, so DST cannot skip or repeat a day.
  let restDaysInRow = 0;
  let dayCursor = localDayKey(now, tz);
  while (!dayKeys.has(dayCursor) && restDaysInRow < 400) {
    restDaysInRow++;
    dayCursor = prevDayKey(dayCursor);
  }

  let longest: TrainingStats["longest"] = null;
  if (inWindow.length > 0) {
    let l = inWindow[0]!;
    for (const a of inWindow) if (a.distanceMeters > l.distanceMeters) l = a;
    longest = {
      id: l.id,
      type: l.type,
      distanceMeters: l.distanceMeters,
      daysAgo: Math.floor((nowMs - Date.parse(l.startDate)) / DAY),
    };
  }

  let medianDistanceSameType: number | null = null;
  if (longest) {
    const sameType = inWindow
      .filter((a) => a.type === longest!.type)
      .map((a) => a.distanceMeters)
      .sort((x, y) => x - y);
    if (sameType.length >= 3) medianDistanceSameType = median(sameType);
  }

  let pacePercentile: number | null = null;
  if (last) {
    const comparables = inWindow
      .filter((a) => a.id !== last.id && a.type === last.type)
      .map((a) => a.averageSpeed);
    if (comparables.length >= 3) {
      const faster = comparables.filter((s) => last.averageSpeed > s).length;
      pacePercentile = faster / comparables.length;
    }
  }

  const lastActivity: LastActivity | null = last
    ? {
        id: last.id,
        name: last.name,
        type: last.type,
        startedAt: last.startDate,
        distanceMeters: last.distanceMeters,
        movingTimeSeconds: last.movingTimeSeconds,
        elevationGainMeters: last.elevationGainMeters,
        averageHeartrate: last.averageHeartrate,
        maxHeartrate: last.maxHeartrate,
        sufferScore: detail?.sufferScore ?? null,
        achievementCount: detail?.achievementCount ?? last.achievementCount,
        kudosCount: last.kudosCount,
      }
    : null;

  return {
    activityCount30d: inWindow.length,
    daysSinceLast,
    gapBeforeLast,
    sessions7d: a7.length,
    sessions28d: a28.length,
    load7d,
    loadWeeklyAvg28d,
    acuteChronicRatio,
    streakWeeks,
    restDaysInRow,
    prCount: lastActivity?.achievementCount ?? 0,
    pacePercentile,
    medianDistanceSameType,
    longest,
    last: lastActivity,
  };
}
```

