import type { MoodId, TrainingStats } from "../types";

export interface Classification {
  mood: MoodId;
  signals: string[];
}

function signalsFor(s: TrainingStats): string[] {
  const out: string[] = [];
  if (s.daysSinceLast === null) out.push("no activity on record");
  else if (s.daysSinceLast === 0) out.push("out today");
  else out.push(`${s.daysSinceLast}d since last out`);

  out.push(`${s.sessions7d} session${s.sessions7d === 1 ? "" : "s"} this week`);
  if (s.acuteChronicRatio !== null) out.push(`load ratio ${s.acuteChronicRatio.toFixed(2)}`);
  if (s.streakWeeks > 0) out.push(`${s.streakWeeks}-week streak`);
  if (s.prCount > 0) out.push(`${s.prCount} PR${s.prCount === 1 ? "" : "s"} last out`);
  if (s.pacePercentile !== null) out.push(`pace top ${Math.round((1 - s.pacePercentile) * 100)}%`);
  return out;
}

export function classify(s: TrainingStats): Classification {
  const signals = signalsFor(s);
  const mood = pickMood(s);
  return { mood, signals };
}

function pickMood(s: TrainingStats): MoodId {
  // Rule 0 — guard.
  if (s.activityCount30d === 0) return "NO_SIGNAL";

  const since = s.daysSinceLast;
  const acr = s.acuteChronicRatio;

  // 1 — back within two days of a gap of ten or more.
  if (since !== null && since <= 2 && s.gapBeforeLast !== null && s.gapBeforeLast >= 10) {
    return "COMEBACK_KID";
  }
  // 2 — gone ten days or more.
  if (since !== null && since >= 10) return "GHOSTED";

  // 3 — five to nine days off.
  if (since !== null && since >= 5 && since <= 9) return "RUSTY";

  // 4 — acute spike on a heavy week.
  if (acr !== null && acr >= 1.5 && s.sessions7d >= 5) return "COOKED";

  // 5 — fresh session with a PR or a top-quintile pace.
  if (since !== null && since <= 2 && (s.prCount >= 1 || (s.pacePercentile !== null && s.pacePercentile >= 0.8))) {
    return "ON_A_HEATER";
  }
  // 6 — the month's longest outing, recently, well over the median.
  if (
    s.longest !== null &&
    s.longest.daysAgo <= 3 &&
    s.medianDistanceSameType !== null &&
    s.longest.distanceMeters >= 1.3 * s.medianDistanceSameType
  ) {
    return "WENT_LONG";
  }
  // 7 — four or more sessions at a sustainable ratio.
  if (s.sessions7d >= 4 && acr !== null && acr >= 0.8 && acr < 1.5) return "GRINDING";

  // 8 — catch-all.
  return "FRESH_LEGS";
}
