/** FNV-1a, 32-bit. Small, stable, and dependency-free. */
export function hashSeed(seed: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

/**
 * Deterministic content selection. Quote and gif read different bits of the
 * hash so they vary independently rather than moving in lockstep.
 */
export function pick(mood: MoodId, seed: string): { quote: Quote; gif: Gif } {
  const entry = MOOD_CATALOG[mood];
  const h = hashSeed(seed);
  const quote = entry.quotes[h % entry.quotes.length]!;
  const gif = entry.gifs[(h >>> 11) % entry.gifs.length]!;
  return { quote, gif };
}
