  type AppEnv,
} from "../src/types";

const FIXED_NOW = Date.parse("2026-08-18T18:00:00Z");

/** A deps object whose fetch returns one canned response and records its calls. */
function deps(status: number, body: unknown): TokenDeps & { calls: Array<{ url: string; body: string }> } {
  const calls: Array<{ url: string; body: string }> = [];
  return {
    calls,
    now: () => FIXED_NOW,
    fetch: (async (input: RequestInfo | URL, init?: RequestInit) => {
      calls.push({ url: String(input), body: String(init?.body ?? "") });
      return new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });
    }) as unknown as typeof fetch,
  };
}

function tokenPayload(over: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    access_token: "new-access",
    refresh_token: "rotated-refresh",
    expires_at: Math.floor(FIXED_NOW / 1000) + 6 * 3600,
    ...over,
  };
}

beforeEach(async () => {
  await env.MOOD_KV.delete(KEY_ACCESS);
  await env.MOOD_KV.delete(KEY_REFRESH);
});

