  it("reuses a cached token with more than 30 minutes left", async () => {
    await env.MOOD_KV.put(KEY_ACCESS, JSON.stringify({ token: "cached", expiresAt: FIXED_NOW + 45 * 60_000 }));
    const d = deps(200, tokenPayload());
    expect(await getAccessToken(env as unknown as AppEnv, d)).toBe("cached");
    expect(d.calls).toHaveLength(0);
  });

  it("refreshes when fewer than 30 minutes remain", async () => {
    await env.MOOD_KV.put(KEY_ACCESS, JSON.stringify({ token: "cached", expiresAt: FIXED_NOW + 10 * 60_000 }));
    await env.MOOD_KV.put(KEY_REFRESH, "old-refresh");
    const d = deps(200, tokenPayload());
    expect(await getAccessToken(env as unknown as AppEnv, d)).toBe("new-access");
    expect(d.calls).toHaveLength(1);
  });

  it("refreshes when the cached token has already expired", async () => {
    await env.MOOD_KV.put(KEY_ACCESS, JSON.stringify({ token: "cached", expiresAt: FIXED_NOW - 1 }));
    await env.MOOD_KV.put(KEY_REFRESH, "old-refresh");
    const d = deps(200, tokenPayload());
    expect(await getAccessToken(env as unknown as AppEnv, d)).toBe("new-access");
  });

  it("stores the new access token with its expiry in milliseconds", async () => {
    await env.MOOD_KV.put(KEY_REFRESH, "old-refresh");
    await getAccessToken(env as unknown as AppEnv, deps(200, tokenPayload()));
    const stored = await env.MOOD_KV.get<{ token: string; expiresAt: number }>(KEY_ACCESS, "json");
    expect(stored?.token).toBe("new-access");
    expect(stored?.expiresAt).toBe((Math.floor(FIXED_NOW / 1000) + 6 * 3600) * 1000);
