describe("getAccessToken refresh-token rotation", () => {
  it("persists a rotated refresh token", async () => {
    await env.MOOD_KV.put(KEY_REFRESH, "old-refresh");
    await getAccessToken(env as unknown as AppEnv, deps(200, tokenPayload()));
    expect(await env.MOOD_KV.get(KEY_REFRESH)).toBe("rotated-refresh");
