    await env.MOOD_KV.put(KEY_REFRESH, "same-refresh");
    await getAccessToken(env as unknown as AppEnv, deps(200, tokenPayload({ refresh_token: "same-refresh" })));
    expect(await env.MOOD_KV.get(KEY_REFRESH)).toBe("same-refresh");
