```typescript
import {
  MissingRefreshTokenError,
  RateLimitedError,
  ReauthRequiredError,
  StravaError,
  type AppEnv,
} from "../types";

const TOKEN_URL = "https://www.strava.com/oauth/token";

/** Refresh early so a poll never races an expiry. Access tokens live 6 hours. */
const REFRESH_MARGIN_MS = 30 * 60 * 1000;

export const KEY_REFRESH = "strava:refresh";
export const KEY_ACCESS = "strava:access";

export interface CachedAccess {
  token: string;
  expiresAt: number;
}

export interface TokenDeps {
  fetch: typeof fetch;
  now: () => number;
}

export const liveDeps: TokenDeps = {
  fetch: (...args: Parameters<typeof fetch>) => globalThis.fetch(...args),
  now: () => Date.now(),
};

export async function getAccessToken(env: AppEnv, deps: TokenDeps = liveDeps): Promise<string> {
  const cached = await env.MOOD_KV.get<CachedAccess>(KEY_ACCESS, "json");
  if (cached?.token && cached.expiresAt - deps.now() > REFRESH_MARGIN_MS) {
    return cached.token;
  }

  const refresh = await env.MOOD_KV.get(KEY_REFRESH);
  if (!refresh) throw new MissingRefreshTokenError();

  const res = await deps.fetch(TOKEN_URL, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: env.STRAVA_CLIENT_ID,
      client_secret: env.STRAVA_CLIENT_SECRET,
      grant_type: "refresh_token",
      refresh_token: refresh,
    }),
  });

  if (res.status === 400 || res.status === 401) {
    throw new ReauthRequiredError(`Strava rejected the refresh token (${res.status})`);
  }
  if (res.status === 429) throw new RateLimitedError("Strava rate limit hit during token refresh");
  if (!res.ok) throw new StravaError(`Token refresh failed with ${res.status}`);

  const data = (await res.json()) as { access_token?: string; refresh_token?: string; expires_at?: number };
  if (!data.access_token || typeof data.expires_at !== "number") {
    throw new StravaError("Token refresh returned an unusable payload");
  }

  // Strava invalidates the previous refresh token the moment it issues a new one.
  // Persist it FIRST and let a write failure abort the entire poll — a snapshot is
  // worth far less than the ability to ever poll again.
  if (data.refresh_token && data.refresh_token !== refresh) {
    try {
      await env.MOOD_KV.put(KEY_REFRESH, data.refresh_token);
    } catch (cause) {
      throw new StravaError(`FATAL: could not persist rotated refresh token: ${String(cause)}`);
    }
  }

  const record: CachedAccess = { token: data.access_token, expiresAt: data.expires_at * 1000 };
  await env.MOOD_KV.put(KEY_ACCESS, JSON.stringify(record));
  return data.access_token;
}
```

