```typescript
import type { DetailExtra } from "../mood/stats";
import { RateLimitedError, ReauthRequiredError, StravaError, type Activity } from "../types";

const API = "https://www.strava.com/api/v3";

export interface ClientDeps {
  fetch: typeof fetch;
}

export const liveClientDeps: ClientDeps = {
  fetch: (...args: Parameters<typeof fetch>) => globalThis.fetch(...args),
};

async function call(url: string, token: string, deps: ClientDeps): Promise<unknown> {
  const res = await deps.fetch(url, { headers: { authorization: `Bearer ${token}` } });
  if (res.status === 401) throw new ReauthRequiredError(`Strava returned 401 for ${url}`);
  if (res.status === 429) throw new RateLimitedError(`Strava rate limit hit for ${url}`);
  if (!res.ok) throw new StravaError(`Strava returned ${res.status} for ${url}`);
  return res.json();
}

function num(v: unknown, fallback = 0): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}

function nullableNum(v: unknown): number | null {
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}

/**
 * The single place location data is dropped. `start_latlng`, `end_latlng`, and
 * `map.summary_polyline` are never copied onto our `Activity`, so nothing
 * downstream can leak them.
 */
function sanitize(r: Record<string, unknown>): Activity {
  return {
    id: num(r.id),
    name: typeof r.name === "string" ? r.name : "Untitled",
    type: typeof r.type === "string" ? r.type : typeof r.sport_type === "string" ? r.sport_type : "Workout",
    startDate: typeof r.start_date === "string" ? r.start_date : new Date(0).toISOString(),
    distanceMeters: num(r.distance),
    movingTimeSeconds: num(r.moving_time),
    elevationGainMeters: num(r.total_elevation_gain),
    averageSpeed: num(r.average_speed),
    averageHeartrate: nullableNum(r.average_heartrate),
    maxHeartrate: nullableNum(r.max_heartrate),
    achievementCount: num(r.achievement_count),
    kudosCount: num(r.kudos_count),
  };
}

export async function fetchActivities(
  token: string,
  afterEpochSeconds: number,
  deps: ClientDeps = liveClientDeps,
): Promise<Activity[]> {
  const url = `${API}/athlete/activities?after=${afterEpochSeconds}&per_page=100`;
  const body = await call(url, token, deps);
  if (!Array.isArray(body)) throw new StravaError("Expected an array of activities");
  return body.map((r) => sanitize(r as Record<string, unknown>));
}

export async function fetchActivityDetail(
  token: string,
  id: number,
  deps: ClientDeps = liveClientDeps,
): Promise<DetailExtra> {
  const body = (await call(`${API}/activities/${id}`, token, deps)) as Record<string, unknown>;
  return {
    sufferScore: nullableNum(body.suffer_score),
    achievementCount: num(body.achievement_count),
  };
}

export async function fetchAthlete(
  token: string,
  deps: ClientDeps = liveClientDeps,
): Promise<{ firstname: string; createdAt: string }> {
  const body = (await call(`${API}/athlete`, token, deps)) as Record<string, unknown>;
  return {
    firstname: typeof body.firstname === "string" && body.firstname.trim() !== "" ? body.firstname : "Athlete",
    createdAt: typeof body.created_at === "string" ? body.created_at : new Date(0).toISOString(),
  };
}
