      headers: { "content-type": "application/json" },
    });

  const routed = (async (input: RequestInfo | URL) => {
    const url = String(input);
    hits.push(url);
    if (url.includes("/oauth/token")) return reply(routes.token ?? { status: 200, body: { access_token: "tok", refresh_token: "r2", expires_at: Math.floor(NOW.getTime() / 1000) + 21_600 } });
    if (url.includes("/athlete/activities")) return reply(routes.activities ?? { status: 200, body: [] });
    if (url.includes("/api/v3/activities/")) return reply(routes.detail ?? { status: 200, body: { suffer_score: 60, achievement_count: 0 } });
    if (url.includes("/api/v3/athlete")) return reply(routes.athlete ?? { status: 200, body: { firstname: "Lizzie", created_at: "2019-04-02T17:11:00Z" } });
    throw new Error(`unrouted url: ${url}`);
  }) as unknown as typeof fetch;

  return {
    hits,
    now: () => NOW,
    tokenDeps: { fetch: routed, now: () => NOW.getTime() },
    clientDeps: { fetch: routed },
  };
}

