```typescript
import { MOOD_CATALOG, pick } from "./content/catalog";
import { classify } from "./mood/classify";
import { summarize, type DetailExtra } from "./mood/stats";
import { fetchActivities, fetchActivityDetail, fetchAthlete, liveClientDeps, type ClientDeps } from "./strava/client";
import { getAccessToken, liveDeps, type TokenDeps } from "./strava/tokens";
import {
  MissingRefreshTokenError,
  ReauthRequiredError,
  type Activity,
  type ActivityLine,
  type AppEnv,
  type Snapshot,
} from "./types";

export const KEY_SNAPSHOT = "snapshot:latest";
export const KEY_ERROR = "snapshot:error";
export const KEY_ATHLETE = "strava:athlete";

const WINDOW_DAYS = 30;
const POLL_INTERVAL_MS = 3 * 3600_000;

export interface PollDeps {
  tokenDeps: TokenDeps;
  clientDeps: ClientDeps;
  now: () => Date;
}

export const livePollDeps: PollDeps = {
  tokenDeps: liveDeps,
  clientDeps: liveClientDeps,
  now: () => new Date(),
};

interface AthleteProfile {
  firstname: string;
  createdAt: string;
}

async function getAthlete(env: AppEnv, token: string, deps: PollDeps): Promise<AthleteProfile> {
  const cached = await env.MOOD_KV.get<AthleteProfile>(KEY_ATHLETE, "json");
  if (cached?.firstname) return cached;
  const fresh = await fetchAthlete(token, deps.clientDeps);
  await env.MOOD_KV.put(KEY_ATHLETE, JSON.stringify(fresh));
  return fresh;
}

function slateNumber(createdAt: string, now: Date): string {
  const days = Math.max(0, Math.floor((now.getTime() - Date.parse(createdAt)) / 86_400_000));
  return `TX-${String(days).padStart(4, "0")}`;
}

function toLine(a: Activity): ActivityLine {
  return {
    name: a.name,
    type: a.type,
    startedAt: a.startDate,
    distanceMeters: a.distanceMeters,
    movingTimeSeconds: a.movingTimeSeconds,
    averageHeartrate: a.averageHeartrate,
  };
}

export async function buildSnapshot(env: AppEnv, deps: PollDeps = livePollDeps): Promise<Snapshot> {
  const now = deps.now();
  const token = await getAccessToken(env, deps.tokenDeps);
  const athlete = await getAthlete(env, token, deps);

  const after = Math.floor((now.getTime() - WINDOW_DAYS * 86_400_000) / 1000);
  const activities = await fetchActivities(token, after, deps.clientDeps);
  const sorted = [...activities].sort((a, b) => Date.parse(b.startDate) - Date.parse(a.startDate));

  // The detail endpoint is the only source of suffer_score, but it is not worth
  // losing an entire poll over. A reauth error still propagates.
  let detail: DetailExtra | null = null;
  const mostRecent = sorted[0];
  if (mostRecent) {
    try {
      detail = await fetchActivityDetail(token, mostRecent.id, deps.clientDeps);
    } catch (cause) {
      if (cause instanceof ReauthRequiredError) throw cause;
      console.warn("activity detail unavailable, continuing without it", cause);
    }
  }

  const stats = summarize(activities, detail, now, env.DISPLAY_TZ);
  const { mood, signals } = classify(stats);
  const content = MOOD_CATALOG[mood];
  const computedAt = now.toISOString();
  const { quote, gif } = pick(mood, computedAt);

  return {
    version: 1,
    computedAt,
    nextReadAt: new Date(now.getTime() + POLL_INTERVAL_MS).toISOString(),
    mood,
    moodLabel: content.label,
    accent: content.accent,
    quote,
    gif,
    signals,
    stats,
    recent: sorted.slice(0, 5).map(toLine),
    athlete: { firstname: athlete.firstname, slateNumber: slateNumber(athlete.createdAt, now) },
  };
}

export async function readSnapshot(env: AppEnv): Promise<Snapshot | null> {
  const raw = await env.MOOD_KV.get(KEY_SNAPSHOT);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as Snapshot;
    return parsed.version === 1 ? parsed : null;
  } catch {
    return null;
  }
}

export async function pollAndStore(
  env: AppEnv,
  deps: PollDeps = livePollDeps,
): Promise<{ ok: boolean; snapshot: Snapshot | null; error?: string }> {
  try {
    const snapshot = await buildSnapshot(env, deps);
    await env.MOOD_KV.put(KEY_SNAPSHOT, JSON.stringify(snapshot));
    await env.MOOD_KV.delete(KEY_ERROR);
    console.log(`poll ok: ${snapshot.mood} at ${snapshot.computedAt}`);
    return { ok: true, snapshot };
  } catch (cause) {
    const reason = cause instanceof Error ? `${cause.name}: ${cause.message}` : String(cause);
    const needsReauth = cause instanceof ReauthRequiredError || cause instanceof MissingRefreshTokenError;
    console.error(`poll failed: ${reason}`);

    await env.MOOD_KV.put(KEY_ERROR, JSON.stringify({ reason, at: deps.now().toISOString() }));

    // Never destroy a good snapshot because of a bad poll. Annotate and keep it.
    const previous = await readSnapshot(env);
    if (previous) {
      const annotated: Snapshot = {
        ...previous,
        stale: { since: previous.stale?.since ?? previous.computedAt, reason },
        ...(needsReauth ? { needsReauth: true } : {}),
      };
      await env.MOOD_KV.put(KEY_SNAPSHOT, JSON.stringify(annotated));
      return { ok: false, snapshot: annotated, error: reason };
    }
    return { ok: false, snapshot: null, error: reason };
  }
}
