import { pollAndStore } from "./snapshot";
import type { AppEnv } from "./types";

export default {
  async fetch(): Promise<Response> {
    return new Response("warming up", { headers: { "content-type": "text/plain" } });
  },

  async scheduled(controller: ScheduledController, env: AppEnv): Promise<void> {
    const result = await pollAndStore(env);
    if (!result.ok) {
      // Surfaced in `wrangler tail`; the page keeps serving the last good read.
      console.error(`scheduled poll at ${controller.cron} failed: ${result.error}`);
    }
  },
} satisfies ExportedHandler<AppEnv>;
