```typescript
import { KEY_ATHLETE, pollAndStore } from "./snapshot";
import { KEY_ACCESS, KEY_REFRESH, type CachedAccess } from "./strava/tokens";
import type { AppEnv } from "./types";

const AUTHORIZE_URL = "https://www.strava.com/oauth/authorize";
const TOKEN_URL = "https://www.strava.com/oauth/token";
const STATE_TTL_SECONDS = 600;

export interface AuthDeps {
  fetch: typeof fetch;
  poll: (env: AppEnv) => Promise<{ ok: boolean }>;
}

export const liveAuthDeps: AuthDeps = {
  fetch: (...args: Parameters<typeof fetch>) => globalThis.fetch(...args),
  poll: (env: AppEnv) => pollAndStore(env),
};

/** Length is not secret; the contents are. */
export function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length || a.length === 0) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

export function isAuthorized(url: URL, env: AppEnv): boolean {
  return timingSafeEqual(url.searchParams.get("k") ?? "", env.SETUP_SECRET);
}

/** Deliberately 404, not 403 — an unauthorised caller learns nothing. */
function notFound(): Response {
  return new Response("Not found", { status: 404, headers: { "content-type": "text/plain" } });
}

export async function handleAuthStart(url: URL, env: AppEnv): Promise<Response> {
  if (!isAuthorized(url, env)) return notFound();

  const state = crypto.randomUUID();
  await env.MOOD_KV.put(`auth:state:${state}`, "1", { expirationTtl: STATE_TTL_SECONDS });

  const target = new URL(AUTHORIZE_URL);
  target.searchParams.set("client_id", env.STRAVA_CLIENT_ID);
  target.searchParams.set("redirect_uri", env.STRAVA_REDIRECT_URI);
  target.searchParams.set("response_type", "code");
  target.searchParams.set("approval_prompt", "auto");
  target.searchParams.set("scope", "activity:read_all");
  target.searchParams.set("state", state);

  return new Response(null, { status: 302, headers: { location: target.toString() } });
}

export async function handleAuthCallback(url: URL, env: AppEnv, deps: AuthDeps = liveAuthDeps): Promise<Response> {
  const code = url.searchParams.get("code");
  const state = url.searchParams.get("state");
  if (!code || !state) return new Response("Missing code or state", { status: 400 });

  const stateKey = `auth:state:${state}`;
  if ((await env.MOOD_KV.get(stateKey)) === null) {
    return new Response("Unrecognised or expired state", { status: 400 });
  }
  // Consume it immediately so the callback cannot be replayed.
  await env.MOOD_KV.delete(stateKey);

  const res = await deps.fetch(TOKEN_URL, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: env.STRAVA_CLIENT_ID,
      client_secret: env.STRAVA_CLIENT_SECRET,
      code,
      grant_type: "authorization_code",
    }),
  });

  if (!res.ok) {
    return new Response(`Strava rejected the authorization code (${res.status})`, { status: 502 });
  }

  const data = (await res.json()) as { access_token?: string; refresh_token?: string; expires_at?: number };
  if (!data.refresh_token || !data.access_token || typeof data.expires_at !== "number") {
    return new Response("Strava returned an unusable token payload", { status: 502 });
  }

  await env.MOOD_KV.put(KEY_REFRESH, data.refresh_token);
  const access: CachedAccess = { token: data.access_token, expiresAt: data.expires_at * 1000 };
  await env.MOOD_KV.put(KEY_ACCESS, JSON.stringify(access));
  // A different athlete may have authorised; force the profile to be refetched.
  await env.MOOD_KV.delete(KEY_ATHLETE);

  await deps.poll(env);
  return new Response(null, { status: 302, headers: { location: "/" } });
}

export async function handleAdminRefresh(url: URL, env: AppEnv, deps: AuthDeps = liveAuthDeps): Promise<Response> {
  if (!isAuthorized(url, env)) return notFound();
  const result = await deps.poll(env);
  return new Response(JSON.stringify(result, null, 2), {
    status: 200,
    headers: { "content-type": "application/json; charset=utf-8" },
  });
}
```

