import { pollAndStore } from "./snapshot";
import type { AppEnv } from "./types";

export default {
  async fetch(request: Request, env: AppEnv): Promise<Response> {
    const url = new URL(request.url);

    switch (url.pathname) {
      case "/auth/start":
        return handleAuthStart(url, env);
      case "/auth/callback":
