    }
  },

  async scheduled(controller: ScheduledController, env: AppEnv): Promise<void> {
    const result = await pollAndStore(env);
    if (!result.ok) {
      console.error(`scheduled poll at ${controller.cron} failed: ${result.error}`);
    }
  },
} satisfies ExportedHandler<AppEnv>;
