```typescript
const METRES_PER_MILE = 1_609.344;
const FOOT_SPORTS = new Set(["Run", "TrailRun", "VirtualRun", "Walk", "Hike", "Snowshoe"]);

export function miles(meters: number): string {
  return (meters / METRES_PER_MILE).toFixed(1);
}

export function duration(seconds: number): string {
  const total = Math.max(0, Math.round(seconds));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  if (h > 0) return `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  return `${m}:${String(s).padStart(2, "0")}`;
}

export function paceMinPerMile(meters: number, seconds: number): string | null {
  if (meters <= 0 || seconds <= 0) return null;
  const secondsPerMile = seconds / (meters / METRES_PER_MILE);
  const m = Math.floor(secondsPerMile / 60);
  const s = Math.round(secondsPerMile % 60);
  if (s === 60) return `${m + 1}:00`;
  return `${m}:${String(s).padStart(2, "0")}`;
}

export function mph(meters: number, seconds: number): string | null {
  if (seconds <= 0) return null;
  return (meters / METRES_PER_MILE / (seconds / 3600)).toFixed(1);
}

export function isFootSport(type: string): boolean {
  return FOOT_SPORTS.has(type);
}

/** "18 AUG 18:30" in the given timezone — broadcast slate style. */
export function stamp(iso: string, tz: string): string {
  const d = new Date(iso);
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: tz,
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).formatToParts(d);
  const get = (type: string): string => parts.find((p) => p.type === type)?.value ?? "";
  return `${get("day")} ${get("month").toUpperCase()} ${get("hour")}:${get("minute")}`;
}

export function relativeDays(days: number | null): string {
  if (days === null) return "NEVER";
  if (days <= 0) return "TODAY";
  if (days === 1) return "YESTERDAY";
  return `${days} DAYS AGO`;
}
```

