/**
 * Aesthetic: a Sky Sports match graphics package. Hard diagonal cuts, condensed
 * all-caps tickers, mono telemetry numerals, a dense stat strip pinned to the
 * bottom and air at the top. Deliberately asymmetric: nothing is centred and no
 * two paddings match by accident.
 *
 * Colour: one accent slot, filled by the mood. Richmond blue is structural only
 * (2.49:1 — borders and fills, never type).
 */
export const STYLESHEET = `
:root {
  --field: #080C12;
  --field-2: #0E141C;
  --bone: #EDE8DF;
  --bone-dim: #9A968E;
  --richmond: #1B4FA0;
  --rule: #1E2833;
  --accent: #EDE8DF;
  --display: "Barlow Condensed", "Arial Narrow", Impact, sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, monospace;
}

*, *::before, *::after { box-sizing: border-box; }

html { background: var(--field); }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--field);
  color: var(--bone);
  font-family: var(--mono);
  font-size: 13px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

.board {
  position: relative;
  min-height: 100vh;
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  grid-template-rows: auto 1fr auto auto;
  column-gap: 20px;
  padding: 22px 34px 0;
  max-width: 1500px;
  margin: 0 auto;
}

/* ---- top rail ------------------------------------------------------- */

.rail {
  grid-column: 1 / -1;
  display: flex;
  align-items: baseline;
  gap: 18px;
  border-bottom: 2px solid var(--rule);
  padding-bottom: 9px;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--bone-dim);
}

.rail__live {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--accent);
  font-weight: 600;
}

.rail__dot {
  width: 8px; height: 8px;
  background: var(--accent);
  border-radius: 50%;
  animation: pulse 2.4s ease-in-out infinite;
}

.rail__slate { color: var(--bone); }
.rail__spacer { flex: 1 1 auto; }
.rail__stale { color: var(--accent); font-weight: 600; }

@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }

/* ---- verdict -------------------------------------------------------- */

.verdict {
  grid-column: 1 / 8;
  padding: 52px 0 26px;
  align-self: start;
}

.verdict__kicker {
  margin: 0 0 6px;
  font-size: 11px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--bone-dim);
}

.verdict__mood {
  margin: 0;
  font-family: var(--display);
  font-weight: 800;
  font-size: clamp(58px, 12.5vw, 168px);
  line-height: 0.84;
  letter-spacing: -0.015em;
  text-transform: uppercase;
  color: var(--accent);
  animation: cut-in 260ms steps(3, end) 1;
}

@keyframes cut-in { from { opacity: 0; transform: translateX(-14px); } to { opacity: 1; transform: none; } }

/* Hairline under the verdict, stopping short of the column edge on purpose. */
.verdict__rule {
  width: 62%;
  height: 1px;
  background: var(--rule);
  margin: 22px 0 20px;
}

.quote { margin: 0; max-width: 34ch; }

.quote p {
  margin: 0;
  font-family: var(--display);
  font-weight: 600;
  font-size: clamp(19px, 2.1vw, 29px);
  line-height: 1.24;
  color: var(--bone);
}

.quote cite {
  display: block;
  margin-top: 13px;
  font-family: var(--mono);
  font-style: normal;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--bone-dim);
}

.signals {
  list-style: none;
  margin: 30px 0 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.signals li {
  border: 1px solid var(--rule);
  border-left: 2px solid var(--accent);
  padding: 3px 8px 3px 7px;
  color: var(--bone-dim);
}

/* ---- exhibit (the gif) ---------------------------------------------- */

.exhibit {
  grid-column: 8 / -1;
  margin: 58px 0 0;
  align-self: start;
}

.exhibit__frame {
  position: relative;
  border: 1px solid var(--rule);
  background: var(--field-2);
  /* Hard diagonal notch, bottom-right — the broadcast lower-third cut. */
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 26px), calc(100% - 26px) 100%, 0 100%);
}

.exhibit__frame::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--accent);
}

.exhibit img {
  display: block;
  width: 100%;
  height: auto;
  filter: saturate(0.92) contrast(1.04);
}

.exhibit figcaption {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 8px;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--bone-dim);
}

/* ---- colour bars (NO SIGNAL) ---------------------------------------- */

.colour-bars {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  height: 190px;
}

.colour-bars span:nth-child(1) { background: #BFBFBF; }
.colour-bars span:nth-child(2) { background: #BFBF00; }
.colour-bars span:nth-child(3) { background: #00BFBF; }
.colour-bars span:nth-child(4) { background: #00BF00; }
.colour-bars span:nth-child(5) { background: #BF00BF; }
.colour-bars span:nth-child(6) { background: #BF0000; }
.colour-bars span:nth-child(7) { background: #0000BF; }

/* ---- stat strip ----------------------------------------------------- */

.strip {
  grid-column: 1 / -1;
  margin-top: 30px;
  border-top: 2px solid var(--rule);
  border-bottom: 1px solid var(--rule);
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
}

.stat {
  flex: 1 1 auto;
  min-width: 118px;
  padding: 11px 16px 12px 0;
  border-right: 1px solid var(--rule);
}

.stat:last-of-type { border-right: 0; }

.stat dt {
  margin: 0 0 3px;
  font-size: 9.5px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--bone-dim);
}

.stat dd {
  margin: 0;
  font-family: var(--display);
  font-weight: 700;
  font-size: 25px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.stat dd small {
  font-family: var(--mono);
  font-weight: 400;
  font-size: 10px;
  letter-spacing: 0.08em;
  color: var(--bone-dim);
  margin-left: 4px;
}

/* The load meter sits 3px low on purpose — hand-placed, not grid-snapped. */
.meter {
  flex: 0 0 168px;
  padding: 14px 0 9px;
  transform: translateY(3px);
}

.meter__label {
  font-size: 9.5px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--bone-dim);
  margin-bottom: 6px;
}

.meter__track {
  position: relative;
  height: 9px;
  border: 1px solid var(--rule);
  background: var(--field-2);
}

.meter__fill { height: 100%; background: var(--accent); }

/* 1.0 reference tick — where a sustainable week sits. */
.meter__tick {
  position: absolute;
  top: -3px; bottom: -3px;
  width: 1px;
  background: var(--bone-dim);
  left: 50%;
}

/* ---- ticker --------------------------------------------------------- */

.ticker {
  grid-column: 1 / -1;
  overflow: hidden;
  border-bottom: 1px solid var(--rule);
  padding: 7px 0;
}

.ticker__track {
  display: inline-flex;
  gap: 34px;
  white-space: nowrap;
  animation: crawl 42s linear infinite;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bone-dim);
  font-variant-numeric: tabular-nums;
}

.ticker:hover .ticker__track,
.ticker:focus-within .ticker__track { animation-play-state: paused; }

.ticker__track b { color: var(--bone); font-weight: 600; }
.ticker__track i { color: var(--accent); font-style: normal; }

@keyframes crawl { from { transform: translateX(0); } to { transform: translateX(-50%); } }

/* ---- footer --------------------------------------------------------- */

.foot {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 22px;
  padding: 12px 0 26px;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--bone-dim);
}

.foot b { color: var(--bone); font-weight: 600; font-variant-numeric: tabular-nums; }
.foot a { color: var(--bone-dim); text-decoration: none; border-bottom: 1px solid var(--rule); }
.foot a:hover, .foot a:focus { color: var(--accent); border-bottom-color: var(--accent); }

/* ---- CRT overlay and registration marks ----------------------------- */

.crt {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background-image: repeating-linear-gradient(
    to bottom,
    rgba(255,255,255,0.019) 0px,
    rgba(255,255,255,0.019) 1px,
    transparent 1px,
    transparent 3px
  );
}

.crt::after {
  content: "";
  position: absolute;
  left: 0; right: 0;
  height: 34vh;
  background: rgba(237,232,223,0.014);
  animation: roll 8.5s linear infinite;
}

@keyframes roll { from { top: -34vh; } to { top: 100%; } }

.regmark {
  position: fixed;
  width: 13px; height: 13px;
  z-index: 2;
  pointer-events: none;
  stroke: var(--rule);
  stroke-width: 1;
}

.regmark--tl { top: 9px; left: 11px; }
.regmark--br { bottom: 9px; right: 11px; }

/* ---- reduced motion ------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
  .rail__dot, .ticker__track, .verdict__mood { animation: none; }
  .crt::after { display: none; }
  .verdict__mood { opacity: 1; transform: none; }
}

/* ---- narrow screens ------------------------------------------------- */

@media (max-width: 860px) {
  .board { padding: 18px 20px 0; column-gap: 0; }
  .verdict { grid-column: 1 / -1; padding-top: 30px; }
  .exhibit { grid-column: 1 / -1; margin-top: 26px; max-width: 420px; }
  .quote { max-width: none; }
  .stat { min-width: 50%; border-right: 0; border-bottom: 1px solid var(--rule); }
  .meter { flex: 1 1 100%; }
}
`;
