```typescript
import type { ActivityLine, Snapshot } from "../types";
import { STYLESHEET } from "./css";
import { duration, isFootSport, mph, miles, paceMinPerMile, relativeDays, stamp } from "./format";

const FONTS =
  "https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800&family=IBM+Plex+Mono:wght@400;600&display=swap";

/** Snapshots older than two missed polls are flagged on the page. */
const STALE_AFTER_MS = 7 * 3600_000;

export function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function statBlock(label: string, value: string, unit?: string): string {
  return `<div class="stat"><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(value)}${
    unit ? `<small>${escapeHtml(unit)}</small>` : ""
  }</dd></div>`;
}

function speedFor(a: { type: string; distanceMeters: number; movingTimeSeconds: number }): { value: string; unit: string } {
  if (isFootSport(a.type)) {
    return { value: paceMinPerMile(a.distanceMeters, a.movingTimeSeconds) ?? "--", unit: "/mi" };
  }
  return { value: mph(a.distanceMeters, a.movingTimeSeconds) ?? "--", unit: "mph" };
}

function tickerItem(a: ActivityLine, tz: string): string {
  const speed = speedFor(a);
  const hr = a.averageHeartrate === null ? "" : ` &middot; ${Math.round(a.averageHeartrate)} bpm`;
  return `<span><i>${escapeHtml(stamp(a.startedAt, tz))}</i> <b>${escapeHtml(a.name)}</b> &middot; ${escapeHtml(
    a.type,
  )} &middot; ${escapeHtml(miles(a.distanceMeters))} mi &middot; ${escapeHtml(duration(a.movingTimeSeconds))} &middot; ${escapeHtml(
    speed.value,
  )}${escapeHtml(speed.unit)}${hr}</span>`;
}

function exhibit(s: Snapshot): string {
  if (s.mood === "NO_SIGNAL") {
    return `<figure class="exhibit">
      <div class="exhibit__frame">
        <div class="colour-bars" role="img" aria-label="Television colour bars, standing in for an absent broadcast">
          <span></span><span></span><span></span><span></span><span></span><span></span><span></span>
        </div>
      </div>
      <figcaption><span>Test card</span><span>No transmission</span></figcaption>
    </figure>`;
  }
  return `<figure class="exhibit">
    <div class="exhibit__frame">
      <img src="${escapeHtml(s.gif.url)}" alt="${escapeHtml(s.gif.alt)}" loading="eager" decoding="async"
           onerror="this.closest('.exhibit').style.display='none'">
    </div>
    <figcaption><span>Exhibit A</span><span>${escapeHtml(s.gif.credit)}</span></figcaption>
  </figure>`;
}

export function renderPage(s: Snapshot, tz: string): string {
  const last = s.stats.last;
  const acr = s.stats.acuteChronicRatio;
  // The meter's midpoint tick marks 1.0, so the scale runs 0 to 2.
  const meterPct = acr === null ? 0 : Math.min(100, Math.round((acr / 2) * 100));

  const aged = Date.now() - Date.parse(s.computedAt) > STALE_AFTER_MS;
  const isStale = Boolean(s.stale) || aged;

  const stats: string[] = [];
  if (last) {
    const speed = speedFor(last);
    stats.push(statBlock("Last out", miles(last.distanceMeters), "mi"));
    stats.push(statBlock("Moving", duration(last.movingTimeSeconds)));
    stats.push(statBlock("Pace", speed.value, speed.unit));
    if (last.averageHeartrate !== null) stats.push(statBlock("Avg HR", String(Math.round(last.averageHeartrate)), "bpm"));
    if (last.sufferScore !== null) stats.push(statBlock("Effort", String(Math.round(last.sufferScore))));
  } else {
    stats.push(statBlock("Last out", "--"));
  }
  stats.push(statBlock("7-day", String(s.stats.sessions7d), s.stats.sessions7d === 1 ? "session" : "sessions"));
  stats.push(statBlock("Streak", String(s.stats.streakWeeks), s.stats.streakWeeks === 1 ? "week" : "weeks"));
  stats.push(statBlock("30-day", String(s.stats.activityCount30d), "out"));
  if (s.stats.prCount > 0) stats.push(statBlock("PRs", String(s.stats.prCount)));

  const tickerBody = s.recent.length
    ? s.recent.map((a) => tickerItem(a, tz)).join("")
    : `<span>No sessions on record in the last 30 days</span>`;

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(s.moodLabel)} &middot; ${escapeHtml(s.athlete.firstname)}'s mood read</title>
<meta name="description" content="A Ted Lasso mood read, computed from Strava training data every three hours.">
<meta name="color-scheme" content="dark">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="${FONTS}">
<style>${STYLESHEET}</style>
</head>
<body style="--accent: ${escapeHtml(s.accent)}">
<main class="board">

  <header class="rail">
    <span class="rail__live"><span class="rail__dot" aria-hidden="true"></span>Live</span>
    <span class="rail__slate">${escapeHtml(s.athlete.slateNumber)}</span>
    <span class="rail__spacer"></span>
    ${isStale ? `<span class="rail__stale">Stale &middot; last read ${escapeHtml(stamp(s.stale?.since ?? s.computedAt, tz))}</span>` : ""}
    <span>Read ${escapeHtml(stamp(s.computedAt, tz))}</span>
  </header>

  <section class="verdict">
    <p class="verdict__kicker">Mood read &middot; ${escapeHtml(s.athlete.firstname)}</p>
    <h1 class="verdict__mood">${escapeHtml(s.moodLabel)}</h1>
    <div class="verdict__rule"></div>
    <blockquote class="quote">
      <p>${escapeHtml(s.quote.text)}</p>
      <cite>${escapeHtml(s.quote.speaker)} &middot; ${escapeHtml(s.quote.source)}</cite>
    </blockquote>
    <ul class="signals">${s.signals.map((sig) => `<li>${escapeHtml(sig)}</li>`).join("")}</ul>
  </section>

  ${exhibit(s)}

  <section class="strip" aria-label="Training numbers">
    <dl style="display:contents">${stats.join("")}</dl>
    <div class="meter">
      <div class="meter__label">Load ratio ${acr === null ? "--" : escapeHtml(acr.toFixed(2))}</div>
      <div class="meter__track" role="img" aria-label="Acute to chronic training load ratio${
        acr === null ? " unavailable" : ` of ${acr.toFixed(2)}, where 1.0 is sustainable`
      }">
        <div class="meter__fill" style="width:${meterPct}%"></div>
        <div class="meter__tick"></div>
      </div>
    </div>
  </section>

  <div class="ticker" tabindex="0" aria-label="Recent sessions">
    <div class="ticker__track">${tickerBody}${tickerBody}</div>
  </div>

  <footer class="foot">
    <span>Next read in <b id="countdown">--</b></span>
    <span>Polls Strava every 3h</span>
    <span>Quotes from <a href="https://www.strava.com" rel="noopener">Ted Lasso</a>, Apple TV+</span>
  </footer>

  <svg class="regmark regmark--tl" viewBox="0 0 13 13" aria-hidden="true"><path d="M6.5 0v13M0 6.5h13" fill="none"/></svg>
  <svg class="regmark regmark--br" viewBox="0 0 13 13" aria-hidden="true"><path d="M6.5 0v13M0 6.5h13" fill="none"/></svg>
  <div class="crt" aria-hidden="true"></div>
</main>
<script>
(function () {
  var target = new Date("${new Date(s.nextReadAt).toISOString()}").getTime();
  var el = document.getElementById("countdown");
  function tick() {
    var left = target - Date.now();
    if (left <= 0) { el.textContent = "any moment"; return; }
    var h = Math.floor(left / 3600000);
    var m = Math.floor((left % 3600000) / 60000);
    var sec = Math.floor((left % 60000) / 1000);
    el.textContent = h > 0 ? h + "h " + m + "m" : m + "m " + sec + "s";
  }
  tick();
  setInterval(tick, 1000);
})();
</script>
</body>
</html>`;
}
```

Note the `<a>` in the footer points at `strava.com` only so the external-host test has a known allowlist; if you prefer no link there, remove it **and** drop `www.strava.com` from that test's allowlist.

