import type { Snapshot } from "../types";
import { STYLESHEET } from "./css";
import { escapeHtml } from "./page";
import { stamp } from "./format";

function shell(accent: string, title: string, body: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<meta name="color-scheme" content="dark">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800&family=IBM+Plex+Mono:wght@400;600&display=swap">
<style>${STYLESHEET}</style>
</head>
<body style="--accent: ${escapeHtml(accent)}">
<main class="board">
${body}
  <svg class="regmark regmark--tl" viewBox="0 0 13 13" aria-hidden="true"><path d="M6.5 0v13M0 6.5h13" fill="none"/></svg>
  <div class="crt" aria-hidden="true"></div>
</main>
</body>
</html>`;
}

/** First deploy: no snapshot yet, and the reader is told exactly what is missing. */
export function renderWarmingUp(): string {
  return shell(
    "#F2C230",
    "Warming up",
    `<header class="rail">
      <span class="rail__live"><span class="rail__dot" aria-hidden="true"></span>Standby</span>
      <span class="rail__spacer"></span>
      <span>No read yet</span>
    </header>
    <section class="verdict">
      <p class="verdict__kicker">Mood read</p>
      <h1 class="verdict__mood">Warming up</h1>
      <div class="verdict__rule"></div>
      <blockquote class="quote">
        <p>No Strava read has landed yet. Authorise the connection at <code>/auth/start</code> with the setup key, and the first read follows immediately.</p>
        <cite>Then every three hours, on the hour</cite>
      </blockquote>
    </section>
    <footer class="foot"><span>Waiting on the first poll</span></footer>`,
  );
}

/** The token is dead. Say so plainly and name the fix. */
export function renderSignalLost(snapshot: Snapshot | null, tz: string): string {
  const lastRead = snapshot ? `Last good read ${stamp(snapshot.stale?.since ?? snapshot.computedAt, tz)}` : "No read on record";
  return shell(
    "#FF2D4B",
    "Signal lost",
    `<header class="rail">
      <span class="rail__live"><span class="rail__dot" aria-hidden="true"></span>Off air</span>
      <span class="rail__spacer"></span>
      <span>${escapeHtml(lastRead)}</span>
    </header>
    <section class="verdict">
      <p class="verdict__kicker">Mood read</p>
      <h1 class="verdict__mood">Signal lost</h1>
      <div class="verdict__rule"></div>
      <blockquote class="quote">
        <p>Strava has stopped accepting the stored credentials. Re-authorise at <code>/auth/start</code> with the setup key and the next read recovers on its own.</p>
        <cite>Nothing is wrong with the training. Only the plumbing.</cite>
      </blockquote>
    </section>
    <footer class="foot"><span>${escapeHtml(lastRead)}</span></footer>`,
  );
}
